query.base:
TS metrics-gcp.bigquery.otel-*
// Legacy streaming API (tabledata.insertAll) rows: DELTA, project-level, ~2 minute publish delay.
// Storage Write API and batch loads are not covered (storage/uploaded_* lags ~6 hours).
| WHERE resource.attributes.gcp.resource_type == "bigquery_project"
// Stage 1: per project/location per minute. DELTA amounts are additive, so SUM is exact across fragmented TSIDs.
// `heartbeat` references query/count and job/num_in_flight, which GCP reports every minute (as 0 when idle),
// so a row exists for every published minute even when no rows were streamed (rows is then null).
| STATS rows = SUM(SUM_OVER_TIME(`metrics.bigquery.googleapis.com/storage/insertall_inserted_rows`)),
        heartbeat = SUM(COUNT_OVER_TIME(`metrics.bigquery.googleapis.com/query/count`)) + SUM(COUNT_OVER_TIME(`metrics.bigquery.googleapis.com/job/num_in_flight`))
    BY @timestamp = TBUCKET(1 minute), resource.attributes.project_id, resource.attributes.location
// Split the 75-minute rule window (relative to rule execution time):
//   baseline = 75..20 minutes ago (55 minutes)
//   recent   = 20..5 minutes ago (15 minutes; the newest 5 minutes may be unpublished and are ignored)
| EVAL period = CASE(
    @timestamp < NOW() - 20 minutes, "baseline",
    @timestamp < NOW() - 5 minutes, "recent",
    "unpublished")
| STATS baseline_rows = SUM(rows) WHERE period == "baseline",
        baseline_active_minutes = COUNT(*) WHERE period == "baseline" AND rows > 0,
        recent_rows = SUM(rows) WHERE period == "recent",
        // COUNT(heartbeat), not COUNT(*): heartbeat must stay referenced or ES|QL prunes it and drops rows-less minutes
        recent_reported_minutes = COUNT(heartbeat) WHERE period == "recent"
    BY resource.attributes.project_id, resource.attributes.location

breach.segment:
// Customise: only evaluate continuous streamers (rows in >= 45 of the 55 baseline minutes)
WHERE baseline_active_minutes >= 45
// The project must still be publishing other BigQuery metrics in the recent period;
// otherwise the gap is a collection or publishing problem, not a stall
| WHERE recent_reported_minutes >= 5
| EVAL baseline_rows_per_min = baseline_rows / 55.0,
       recent_rows = COALESCE(recent_rows, 0)
| EVAL recent_rows_per_min = recent_rows / 15.0
| EVAL drop_pct = ROUND(100.0 - recent_rows_per_min * 100.0 / baseline_rows_per_min, 1)
// Customise: alert when the streaming rate fell by >= 90% versus the baseline (100 = fully stalled)
| WHERE drop_pct >= 90.0
| EVAL baseline_rows_per_min = ROUND(baseline_rows_per_min, 1), recent_rows_per_min = ROUND(recent_rows_per_min, 1)
| KEEP resource.attributes.project_id, resource.attributes.location, drop_pct, recent_rows_per_min, baseline_rows_per_min, baseline_active_minutes, recent_reported_minutes
| SORT drop_pct DESC
| LIMIT 50
